<template>
<section class="recipient-cbr">
  <h3>Recipient-level event prediction</h3>
  <p>Three complete baseline months. Effects start at +1; missing data and insufficient support remain unavailable.</p>
  <AnalysisProfilePicker purpose="prediction" :current-settings="currentSettings" :applied="result?.analysis_profile || appliedProfile" @change="changeProfile" />
  <details><summary>Recipient similarity features ({{selectedFeatures.length}} selected)</summary><div class="pair-features"><label v-for="f in featureCatalog" :key="f.key"><input type="checkbox" v-model="selectedFeatures" :value="f.key">{{f.label}} ({{f.group}})</label></div><label>Weighting<select v-model="weightingMode"><option value="equal_per_feature">Equal per feature</option><option value="equal_per_group">Equal per group</option></select></label></details>
  <div class="options">
    <label>Analysis unit<select v-model="analysisUnit" aria-label="Recipient analysis unit"><option value="event">Raw event (existing benchmark)</option><option value="episode">Grouped site/month episode (experimental)</option></select></label>
    <label>Analysis event<select v-model="eventKey" aria-label="Recipient analysis event"><option v-for="e in events" :value="e.event_key" :key="e.event_key">{{e.date}} · {{e.label}}</option></select></label>
    <label>Method<select v-model="method" aria-label="Recipient CBR method"><option value="pair_cbr">Gaussian recipient CBR</option><option value="control_adjusted">Matched-control adjusted CBR</option><option value="local_linear">CBR + local ridge (experimental)</option><option value="did_local_linear">Control-adjusted CBR + local ridge (experimental)</option></select></label>
    <label>Scope<select v-model="scope" aria-label="Recipient CBR scope"><option value="tier1">{{metadata.scope_labels?.tier1 || 'Tier 1'}}</option><option value="tier2">{{metadata.scope_labels?.tier2 || 'Tier 2'}}</option><option value="cluster" :disabled="metadata.cluster_id===-1">Real cluster</option><option value="virtual_cluster" :disabled="metadata.cluster_id!==-1">Virtual sampled traffic</option><option value="distance_0_2">0-2 km</option><option value="distance_2_5">2-5 km</option><option value="distance_5_10">5-10 km</option></select></label>
    <label>KPI<select v-model="metric" aria-label="Recipient CBR KPI"><option value="downlink_traffic_gb">Downlink traffic (GB/month)</option><option value="active_users" :disabled="scope==='virtual_cluster'">Active users</option><option value="cqi_avg" :disabled="scope==='virtual_cluster'">CQI</option><option value="dl_throughput_kbps" :disabled="scope==='virtual_cluster'">Throughput (kbit/s)</option><option value="dl_packet_delay_ms" :disabled="scope==='virtual_cluster'">Latency (ms)</option></select></label>
    <label class="check"><input type="checkbox" v-model="ramp"> Smooth the supported +1…+6 ramp</label>
  </div>
  <details v-if="analysisUnit==='episode'"><summary>Episode actions and original event dates</summary><p v-for="a in events.find(e=>e.event_key===eventKey)?.actions || []" :key="a.event_key">{{a.effective_date}} | {{a.event_type}} | {{a.cell_ids.join(', ')}} <span v-if="a.previous_bandwidth_mhz!=null"> | {{a.previous_bandwidth_mhz}} to {{a.new_bandwidth_mhz}} MHz</span></p><p>One analysis per physical site/month. Separate months stay separate. Raw detections are preserved. Episode forecasts require separate validation and interval calibration.</p></details>
  <button @click="predict" :disabled="loading || !eventKey">{{loading?'Calculating recipient cases…':'Calculate recipient impact'}}</button>
  <p v-if="error" role="alert">{{error}}</p><p v-if="!loading && !events.length">No recorded event is available for this site.</p>
  <template v-if="result">
    <aside><strong>{{result.method_label}}</strong> · cutoff {{result.query.event_date}}<p v-if="result.analysis_profile?.name">Profile: {{result.analysis_profile.name}} revision {{result.analysis_profile.revision}}</p><p>Scoring: {{result.scoring_settings.selected_features?.join(', ') || 'built-in pair features'}}; {{result.scoring_settings.weighting_mode || 'equal_per_group'}}.</p><p>Baseline: {{result.baseline_kind}}. Model: {{result.model_version}}.</p><p v-if="result.training_snapshot">Training snapshot through {{result.training_snapshot.latest_complete_month}} - {{result.training_snapshot.pairs.toLocaleString()}} recipient cases.</p><p>{{result.interval_note}}</p><p v-if="method.includes('control') || method==='did_local_linear'">{{result.control_note}}</p><p>{{result.aggregation_note}}</p></aside>
    <aside v-if="result.other_site_actions?.length" class="action-context"><strong>Other actions at the event site</strong><p v-for="a in result.other_site_actions" :key="a.date">{{a.date.slice(0,7)}}: {{a.event_count}} {{a.phase}} action(s) - {{a.event_types.join(', ')}}</p><p>Post-event observations include these actions. Their effects are not isolated by a single-event forecast. This is retrospective context, used only for display.</p></aside>
    <p v-if="result.validation_benchmark?.[0]?.skill < 0" class="warning">Across the sampled per-recipient validation, the unsmoothed Gaussian CBR has higher +1 MAE than last-month persistence ({{number(result.validation_benchmark[0].cbr_mae)}} versus {{number(result.validation_benchmark[0].last_month_mae)}}). This is an experimental estimate; it is not a site-specific accuracy score.</p>
    <p v-if="result.status!=='available'" class="warning">This selection has insufficient historical support. Reasons are shown below.</p>
    <div class="options"><label>Display<select v-model="recipient" aria-label="Recipient result"><option value="scope">Complete selected scope</option><option v-for="r in result.recipients" :key="r.site_id" :value="r.site_id">{{r.site_name}} · {{r.site_id}} · {{(r.distance_m/1000).toFixed(2)}} km</option></select></label>
    <label>Interval<select v-model="interval" aria-label="Recipient interval type"><option value="mean">Conditional mean interval (event bootstrap)</option><option value="prediction">Calibrated individual prediction interval</option></select></label></div>
    <p v-if="interval==='prediction'">Prediction bands require at least 20 prior independent event origins plus a rolling coverage check. Missing bands are unavailable; mean intervals are not substituted.</p>
    <p v-if="selected">Recipient baseline: {{number(selected.baseline)}} {{result.metric_definition.unit}} - {{selected.baseline_months}} / 3 complete months.</p>
    <div v-if="points.some(p=>p.predicted!=null || p.observed!=null || p.last_month_forecast!=null)" class="chart"><canvas ref="canvas" role="img" aria-label="Recipient event forecast by horizon"></canvas></div>
    <div class="table-scroll"><table><thead><tr><th>Month</th><th>Observed</th><th>Predicted</th><th>Last-month benchmark</th><th>Predicted change</th><th>Observed change</th><th>Error (% of observed)</th><th>Mean 95% interval</th><th>Prediction 95% interval</th><th>Events / independent origins</th><th>Effective origins</th><th>Min. shared weight</th><th>Support / reason</th></tr></thead><tbody><tr v-for="p in points" :key="p.horizon"><td>+{{p.horizon}} · {{p.month.slice(0,7)}}</td><td>{{number(p.observed)}}</td><td>{{number(p.predicted)}}</td><td>{{number(p.last_month_forecast)}}</td><td>{{number(p.predicted_change)}}</td><td>{{number(p.observed_change)}}</td><td>{{number(p.accuracy?.absolute_percentage_error)}}</td><td>{{range(p.mean_interval_95)}}</td><td>{{range(p.prediction_interval_95)}}</td><td>{{p.support?.n_events ?? '—'}} / {{p.support?.n_event_sites ?? '—'}}</td><td>{{number(p.support?.effective_event_n)}}</td><td>{{p.support?.available_weight_share_min == null ? 'Unavailable' : Math.round(p.support.available_weight_share_min*100)+'%'}}</td><td>{{p.support?.reason || p.calibration?.reason || `${p.supported_recipients ?? 0}/${p.eligible_recipients ?? 0} recipients`}}</td></tr></tbody></table></div>
    <details v-if="selected?.controls"><summary>Matched controls and pre-trend diagnostics</summary><p>{{selected.controls.status}} · {{selected.controls.reason || 'Pre-event matching passed; parallel trends are not established.'}} · exclusion {{selected.controls.exclusion_m/1000}} km</p><table><thead><tr><th>Control</th><th>Weight</th><th>Pre-trend gap</th></tr></thead><tbody><tr v-for="c in selected.controls.controls" :key="c.site_id"><td>{{c.site_name}} · {{c.site_id}}</td><td>{{number(c.weight)}}</td><td>{{number(c.pretrend_gap)}}</td></tr></tbody></table><div v-if="selected.controls.treated_pre_values" class="table-scroll"><table><thead><tr><th>Pre-event month</th><th>Recipient</th><th>Matched control mean</th></tr></thead><tbody><tr v-for="(v,i) in selected.controls.treated_pre_values" :key="i"><td>{{i-selected.controls.treated_pre_values.length}}</td><td>{{number(v)}}</td><td>{{number(selected.controls.controls.reduce((sum,c)=>sum+c.weight*c.pre_values[i],0))}}</td></tr></tbody></table></div></details>
  </template>
</section>
</template>
<script setup>
import {ref,computed,watch,nextTick,onBeforeUnmount} from 'vue';
import axios from 'axios';
import AnalysisProfilePicker from './AnalysisProfilePicker.vue';
import {analysisApi,loadProfiles} from '../analysisProfiles';
import {Chart} from 'chart.js';
const props=defineProps({siteId:{type:String,required:true}}),API='http://localhost:8000/api/cbr/recipients/';
const metadata=ref({}),events=ref([]),eventKey=ref(''),method=ref('pair_cbr'),scope=ref('tier1'),metric=ref('downlink_traffic_gb'),ramp=ref(false),loading=ref(false),error=ref(''),result=ref(null),recipient=ref('scope'),interval=ref('mean'),canvas=ref(null);
const analysisUnit=ref('event');
const profileId=ref(''),profileSettings=ref({}),appliedProfile=ref(null),selectedFeatures=ref([]),featureCatalog=ref([]),weightingMode=ref('equal_per_group');
loadProfiles().then(d=>{featureCatalog.value=d.catalog.prediction_features;if(!selectedFeatures.value.length)selectedFeatures.value=d.catalog.defaults.prediction_features;}).catch(()=>{});
const currentSettings=computed(()=>({...profileSettings.value,prediction_features:selectedFeatures.value,weighting_mode:weightingMode.value,prediction_method:method.value,scope:scope.value,ramp:ramp.value}));
function applySettings(settings){if(!settings)return;profileSettings.value=settings;selectedFeatures.value=[...settings.prediction_features];weightingMode.value=settings.weighting_mode;method.value=settings.prediction_method;scope.value=settings.scope;ramp.value=settings.ramp;}
function changeProfile(p){appliedProfile.value=null;profileId.value=p.id;if(p.settings)applySettings(p.settings);else if(!p.id)applyEventDefault();result.value=null;}
function applyEventDefault(){if(profileId.value)return;const p=events.value.find(e=>e.event_key===eventKey.value)?.analysis_profile;appliedProfile.value=p;applySettings(p?.settings);}
watch(eventKey,applyEventDefault);

let request=0,metadataRequest=0,chart=null;
const selected=computed(()=>result.value?.recipients.find(r=>r.site_id===recipient.value));
const points=computed(()=>recipient.value==='scope'?result.value?.scope_series||[]:selected.value?.points||[]);
function number(v){return v==null?'Unavailable':Number(v).toLocaleString(undefined,{maximumFractionDigits:3});}
function range(v){return v?`${number(v[0])} – ${number(v[1])}`:'Unavailable';}
watch([()=>props.siteId,analysisUnit],async ([id])=>{const token=++metadataRequest;request++;result.value=null;events.value=[];eventKey.value='';loading.value=true;try{const r=await analysisApi.get('/cbr/recipients/',{params:{site_id:id,metadata:'true',analysis_unit:analysisUnit.value}});if(token!==metadataRequest)return;metadata.value=r.data;events.value=r.data.events;eventKey.value=r.data.default_event_key||'';}catch(e){if(token===metadataRequest)error.value=e.response?.data?.error||'Could not load recorded events.';}finally{if(token===metadataRequest)loading.value=false;}},{immediate:true});
watch(scope,s=>{if(s==='virtual_cluster')metric.value='downlink_traffic_gb';});
watch([eventKey,method,scope,metric,ramp,selectedFeatures,weightingMode,profileId],()=>{request++;loading.value=false;result.value=null;error.value='';});
async function predict(){const token=++request;loading.value=true;error.value='';result.value=null;try{const r=await analysisApi.get('/cbr/recipients/',{params:{analysis_unit:analysisUnit.value,profile_id:profileId.value,features:selectedFeatures.value.join(','),weighting_mode:weightingMode.value,site_id:props.siteId,event_key:eventKey.value,method:method.value,scope:scope.value,metric:metric.value,ramp:String(ramp.value)}});if(token===request){result.value=r.data;recipient.value='scope';}}catch(e){if(token===request)error.value=e.response?.data?.error||'Recipient CBR failed.';}finally{if(token===request)loading.value=false;}}
watch([points,interval],async()=>{await nextTick();draw();});
function draw(){if(chart){chart.destroy();chart=null;}if(!canvas.value)return;const rows=points.value,key=interval.value==='mean'?'mean_interval_95':'prediction_interval_95';chart=new Chart(canvas.value,{type:'line',data:{labels:rows.map(p=>'+'+p.horizon+' '+p.month.slice(0,7)),datasets:[{label:'Observed (display only)',data:rows.map(p=>p.observed),borderColor:'#64748b',spanGaps:false},{label:'Recipient forecast',data:rows.map(p=>p.predicted),borderColor:'#2563eb',spanGaps:false},{label:interval.value==='mean'?'Mean interval lower':'Prediction interval lower',data:rows.map(p=>p[key]?.[0]??null),borderColor:'#93c5fd',pointRadius:0},{label:interval.value==='mean'?'Mean interval upper':'Prediction interval upper',data:rows.map(p=>p[key]?.[1]??null),borderColor:'#93c5fd',pointRadius:0,fill:2,backgroundColor:'#dbeafe88'},{label:'Last-month benchmark (not event impact)',data:rows.map(p=>p.last_month_forecast),borderColor:'#16a34a',borderDash:[4,4],spanGaps:false}]},options:{responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{position:'bottom'}},scales:{y:{min:0}}}});}
onBeforeUnmount(()=>{request++;metadataRequest++;if(chart)chart.destroy();});
</script>
<style scoped>
.pair-features{max-height:220px;overflow:auto;display:grid;gap:7px;margin:10px 0}.pair-features label{display:block}
.recipient-cbr{margin-top:20px;padding:18px;background:white;border:1px solid #cbd5e1;border-radius:10px}.options{display:flex;flex-wrap:wrap;gap:12px;margin:12px 0}label{display:grid;gap:5px;font-size:13px;min-width:0;max-width:100%}select{min-width:0;max-width:100%;width:100%}.check{display:flex;align-items:center}select,button{padding:9px;border-radius:6px;border:1px solid #cbd5e1}button{background:#2563eb;color:white}button:disabled{opacity:.5}aside{background:#eff6ff;padding:12px;margin:12px 0;font-size:12px}.warning,[role=alert]{color:#991b1b}.chart{height:340px;margin:16px 0}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:8px;border-bottom:1px solid #e2e8f0;white-space:nowrap}details{margin-top:14px}
</style>
